<?php

use App\Enums\BreedType;
use App\Models\User;
use App\Services\Media\BreedColourCatalogue;

use function Pest\Laravel\getJson;

/*
 * Colour photos in the app's colour picker (David 2026-11-16): GET /api/breeds
 * colours[].image_url = the website register's AI photo of the breed in that colour
 * (config/breed_colour_images.php, generated by scripts/export-breed-registry.mjs).
 */

it('generated colour-image config only names standard colours of known breeds, under the website species folders', function () {
    $images = config('breed_colour_images');
    expect($images)->toBeArray()->not->toBeEmpty();

    foreach ($images as $breed => $colours) {
        $type = BreedType::tryFrom($breed);
        expect($type)->not->toBeNull("unknown breed {$breed}");
        $keys = array_column(app(BreedColourCatalogue::class)->for($type), 'key');
        $folder = $type->species()->value === 'cat' ? 'cats' : 'dogs';

        foreach ($colours as $key => $path) {
            expect($keys)->toContain($key)
                ->and($path)->toMatch('#^'.$folder.'/[a-z0-9-]+(--[a-z0-9-]+)?\.webp$#');
        }
    }
});

it('generated colour-image config matches the committed breed registry export', function () {
    $registryFile = base_path('../docs/research/breed-registry.json');
    if (! is_file($registryFile)) {
        $this->markTestSkipped('breed-registry.json not available outside the monorepo');
    }
    $registry = json_decode((string) file_get_contents($registryFile), true, flags: JSON_THROW_ON_ERROR);

    foreach ($registry['breeds'] as $breed) {
        foreach ($breed['portrait']['colours'] ?? [] as $colour) {
            expect(config("breed_colour_images.{$breed['id']}.{$colour['key']}"))
                ->toEndWith('/'.basename($colour['file']));
        }
    }
});

it('GET /api/breeds sends image_url for colours with a photo and null otherwise', function () {
    config([
        'media.breed_portraits.public_base_url' => 'https://example.test/animals',
        'breed_colour_images.french_bulldog' => ['brindle' => 'dogs/french-bulldog--brindle.webp'],
    ]);
    actingAsRole(User::factory()->parent()->create());

    $breeds = collect(getJson('/api/breeds')->assertOk()->json('breeds'))->keyBy('breed');
    $colours = collect($breeds['french_bulldog']['colours'])->keyBy('key');

    expect($colours['brindle']['image_url'])->toBe('https://example.test/animals/dogs/french-bulldog--brindle.webp')
        ->and($colours['fawn']['image_url'])->toBeNull()
        ->and($breeds['mutt']['colours'])->toBe([]);
});

it('the Border Collie has a photo for every colour', function () {
    $catalogue = app(BreedColourCatalogue::class);

    foreach ($catalogue->pickerFor(BreedType::BorderCollie, 'en') as $colour) {
        expect($colour['image_url'])->toStartWith(config('media.breed_portraits.public_base_url').'/dogs/border-collie');
    }
});
